25	// Language: Verilog 2001
26	
27	`resetall
28	`timescale 1ns / 1ps
29	`default_nettype none
30	
31	/*
32	 * UDP checksum calculation module
33	 */
34	module udp_checksum_gen #
35	(
36	    parameter PAYLOAD_FIFO_DEPTH = 2048,
37	    parameter HEADER_FIFO_DEPTH = 8
38	)
39	(
40	    input  wire        clk,
41	    input  wire        rst,
42	    
43	    /*
44	     * UDP frame input
45	     */
46	    input  wire        s_udp_hdr_valid,
47	    output wire        s_udp_hdr_ready,
48	    input  wire [47:0] s_eth_dest_mac,
49	    input  wire [47:0] s_eth_src_mac,
50	    input  wire [15:0] s_eth_type,
51	    input  wire [3:0]  s_ip_version,
52	    input  wire [3:0]  s_ip_ihl,
53	    input  wire [5:0]  s_ip_dscp,
54	    input  wire [1:0]  s_ip_ecn,
55	    input  wire [15:0] s_ip_identification,
56	    input  wire [2:0]  s_ip_flags,
57	    input  wire [12:0] s_ip_fragment_offset,
58	    input  wire [7:0]  s_ip_ttl,
59	    input  wire [15:0] s_ip_header_checksum,
60	    input  wire [31:0] s_ip_source_ip,
61	    input  wire [31:0] s_ip_dest_ip,
62	    input  wire [15:0] s_udp_source_port,
63	    input  wire [15:0] s_udp_dest_port,
64	    input  wire [7:0]  s_udp_payload_axis_tdata,
65	    input  wire        s_udp_payload_axis_tvalid,
66	    output wire        s_udp_payload_axis_tready,
67	    input  wire        s_udp_payload_axis_tlast,
68	    input  wire        s_udp_payload_axis_tuser,
69	    
70	    /*
71	     * UDP frame output
72	     */
73	    output wire        m_udp_hdr_valid,
74	    input  wire        m_udp_hdr_ready,
75	    output wire [47:0] m_eth_dest_mac,
76	    output wire [47:0] m_eth_src_mac,
77	    output wire [15:0] m_eth_type,
78	    output wire [3:0]  m_ip_version,
79	    output wire [3:0]  m_ip_ihl,
80	    output wire [5:0]  m_ip_dscp,
81	    output wire [1:0]  m_ip_ecn,
82	    output wire [15:0] m_ip_length,
83	    output wire [15:0] m_ip_identification,
84	    output wire [2:0]  m_ip_flags,
85	    output wire [12:0] m_ip_fragment_offset,
86	    output wire [7:0]  m_ip_ttl,
87	    output wire [7:0]  m_ip_protocol,
88	    output wire [15:0] m_ip_header_checksum,
89	    output wire [31:0] m_ip_source_ip,
90	    output wire [31:0] m_ip_dest_ip,
91	    output wire [15:0] m_udp_source_port,
92	    output wire [15:0] m_udp_dest_port,
93	    output wire [15:0] m_udp_length,
94	    output wire [15:0] m_udp_checksum,
95	    output wire [7:0]  m_udp_payload_axis_tdata,
96	    output wire        m_udp_payload_axis_tvalid,
97	    input  wire        m_udp_payload_axis_tready,
98	    output wire        m_udp_payload_axis_tlast,
99	    output wire        m_udp_payload_axis_tuser,
100	    
101	    /*
102	     * Status signals
103	     */
104	    output wire        busy
105	);
106	
107	/*
108	
109	UDP Frame
110	
111	 Field                       Length
112	 Destination MAC address     6 octets
113	 Source MAC address          6 octets
114	 Ethertype (0x0800)          2 octets
115	 Version (4)                 4 bits
116	 IHL (5-15)                  4 bits
117	 DSCP (0)                    6 bits
118	 ECN (0)                     2 bits
119	 length                      2 octets
120	 identification (0?)         2 octets
121	 flags (010)                 3 bits
122	 fragment offset (0)         13 bits
123	 time to live (64?)          1 octet
124	 protocol                    1 octet
125	 header checksum             2 octets
126	 source IP                   4 octets
127	 destination IP              4 octets
128	 options                     (IHL-5)*4 octets
129	
130	 source port                 2 octets
131	 desination port             2 octets
132	 length                      2 octets
133	 checksum                    2 octets
134	
135	 payload                     length octets
136	
137	This module receives a UDP frame with header fields in parallel and payload on
138	an AXI stream interface, calculates the length and checksum, then produces the
139	header fields in parallel along with the UDP payload in a separate AXI stream.
140	
141	*/
142	
143	parameter HEADER_FIFO_ADDR_WIDTH = $clog2(HEADER_FIFO_DEPTH);
144	
145	localparam [2:0]
146	    STATE_IDLE = 3'd0,
147	    STATE_SUM_HEADER_1 = 3'd1,
148	    STATE_SUM_HEADER_2 = 3'd2,
149	    STATE_SUM_HEADER_3 = 3'd3,
150	    STATE_SUM_PAYLOAD = 3'd4,
151	    STATE_FINISH_SUM = 3'd5;
152	
153	reg [2:0] state_reg = STATE_IDLE, state_next;
154	
155	// datapath control signals
156	reg store_udp_hdr;
157	reg shift_payload_in;
158	reg [31:0] checksum_part;
159	
160	reg [15:0] frame_ptr_reg = 16'd0, frame_ptr_next;
161	
162	reg [31:0] checksum_reg = 32'd0, checksum_next;
163	
164	reg [47:0] eth_dest_mac_reg = 48'd0;
165	reg [47:0] eth_src_mac_reg = 48'd0;
166	reg [15:0] eth_type_reg = 16'd0;
167	reg [3:0]  ip_version_reg = 4'd0;
168	reg [3:0]  ip_ihl_reg = 4'd0;
169	reg [5:0]  ip_dscp_reg = 6'd0;
170	reg [1:0]  ip_ecn_reg = 2'd0;
171	reg [15:0] ip_identification_reg = 16'd0;
172	reg [2:0]  ip_flags_reg = 3'd0;
173	reg [12:0] ip_fragment_offset_reg = 13'd0;
174	reg [7:0]  ip_ttl_reg = 8'd0;
175	reg [15:0] ip_header_checksum_reg = 16'd0;
176	reg [31:0] ip_source_ip_reg = 32'd0;
177	reg [31:0] ip_dest_ip_reg = 32'd0;
178	reg [15:0] udp_source_port_reg = 16'd0;
179	reg [15:0] udp_dest_port_reg = 16'd0;
180	
181	reg hdr_valid_reg = 0, hdr_valid_next;
182	
183	reg s_udp_hdr_ready_reg = 1'b0, s_udp_hdr_ready_next;
184	reg s_udp_payload_axis_tready_reg = 1'b0, s_udp_payload_axis_tready_next;
185	
186	reg busy_reg = 1'b0;
187	
188	/*
189	 * UDP Payload FIFO
190	 */
191	wire [7:0] s_udp_payload_fifo_tdata;
192	wire s_udp_payload_fifo_tvalid;
193	wire s_udp_payload_fifo_tready;
194	wire s_udp_payload_fifo_tlast;
195	wire s_udp_payload_fifo_tuser;
196	
197	wire [7:0] m_udp_payload_fifo_tdata;
198	wire m_udp_payload_fifo_tvalid;
199	wire m_udp_payload_fifo_tready;
200	wire m_udp_payload_fifo_tlast;
201	wire m_udp_payload_fifo_tuser;
202	
203	axis_fifo #(
204	    .DEPTH(PAYLOAD_FIFO_DEPTH),
205	    .DATA_WIDTH(8),
206	    .KEEP_ENABLE(0),
207	    .LAST_ENABLE(1),
208	    .ID_ENABLE(0),
209	    .DEST_ENABLE(0),
210	    .USER_ENABLE(1),
211	    .USER_WIDTH(1),
212	    .FRAME_FIFO(0)
213	)
214	payload_fifo (
215	    .clk(clk),
216	    .rst(rst),
217	    // AXI input
218	    .s_axis_tdata(s_udp_payload_fifo_tdata),
219	    .s_axis_tkeep(0),
220	    .s_axis_tvalid(s_udp_payload_fifo_tvalid),
221	    .s_axis_tready(s_udp_payload_fifo_tready),
222	    .s_axis_tlast(s_udp_payload_fifo_tlast),
223	    .s_axis_tid(0),
224	    .s_axis_tdest(0),
225	    .s_axis_tuser(s_udp_payload_fifo_tuser),
226	    // AXI output
227	    .m_axis_tdata(m_udp_payload_fifo_tdata),
228	    .m_axis_tkeep(),
229	    .m_axis_tvalid(m_udp_payload_fifo_tvalid),
230	    .m_axis_tready(m_udp_payload_fifo_tready),
231	    .m_axis_tlast(m_udp_payload_fifo_tlast),
232	    .m_axis_tid(),
233	    .m_axis_tdest(),
234	    .m_axis_tuser(m_udp_payload_fifo_tuser),
235	    // Status
236	    .status_overflow(),
237	    .status_bad_frame(),
238	    .status_good_frame()
239	);
240	
241	assign s_udp_payload_fifo_tdata = s_udp_payload_axis_tdata;
242	assign s_udp_payload_fifo_tvalid = s_udp_payload_axis_tvalid && shift_payload_in;
243	assign s_udp_payload_axis_tready = s_udp_payload_fifo_tready && shift_payload_in;
244	assign s_udp_payload_fifo_tlast = s_udp_payload_axis_tlast;
245	assign s_udp_payload_fifo_tuser = s_udp_payload_axis_tuser;
246	
247	assign m_udp_payload_axis_tdata = m_udp_payload_fifo_tdata;
248	assign m_udp_payload_axis_tvalid = m_udp_payload_fifo_tvalid;
249	assign m_udp_payload_fifo_tready = m_udp_payload_axis_tready;
250	assign m_udp_payload_axis_tlast = m_udp_payload_fifo_tlast;
251	assign m_udp_payload_axis_tuser = m_udp_payload_fifo_tuser;
252	
253	/*
254	 * UDP Header FIFO
255	 */
256	reg [HEADER_FIFO_ADDR_WIDTH:0] header_fifo_wr_ptr_reg = {HEADER_FIFO_ADDR_WIDTH+1{1'b0}}, header_fifo_wr_ptr_next;
257	reg [HEADER_FIFO_ADDR_WIDTH:0] header_fifo_rd_ptr_reg = {HEADER_FIFO_ADDR_WIDTH+1{1'b0}}, header_fifo_rd_ptr_next;
258	
259	reg [47:0] eth_dest_mac_mem[(2**HEADER_FIFO_ADDR_WIDTH)-1:0];
260	reg [47:0] eth_src_mac_mem[(2**HEADER_FIFO_ADDR_WIDTH)-1:0];
261	reg [15:0] eth_type_mem[(2**HEADER_FIFO_ADDR_WIDTH)-1:0];
262	reg [3:0] ip_version_mem[(2**HEADER_FIFO_ADDR_WIDTH)-1:0];
263	reg [3:0] ip_ihl_mem[(2**HEADER_FIFO_ADDR_WIDTH)-1:0];
264	reg [5:0] ip_dscp_mem[(2**HEADER_FIFO_ADDR_WIDTH)-1:0];
265	reg [1:0] ip_ecn_mem[(2**HEADER_FIFO_ADDR_WIDTH)-1:0];
266	reg [15:0] ip_identification_mem[(2**HEADER_FIFO_ADDR_WIDTH)-1:0];
267	reg [2:0] ip_flags_mem[(2**HEADER_FIFO_ADDR_WIDTH)-1:0];
268	reg [12:0] ip_fragment_offset_mem[(2**HEADER_FIFO_ADDR_WIDTH)-1:0];
269	reg [7:0] ip_ttl_mem[(2**HEADER_FIFO_ADDR_WIDTH)-1:0];
270	reg [15:0] ip_header_checksum_mem[(2**HEADER_FIFO_ADDR_WIDTH)-1:0];
271	reg [31:0] ip_source_ip_mem[(2**HEADER_FIFO_ADDR_WIDTH)-1:0];
272	reg [31:0] ip_dest_ip_mem[(2**HEADER_FIFO_ADDR_WIDTH)-1:0];
273	reg [15:0] udp_source_port_mem[(2**HEADER_FIFO_ADDR_WIDTH)-1:0];
274	reg [15:0] udp_dest_port_mem[(2**HEADER_FIFO_ADDR_WIDTH)-1:0];
275	reg [15:0] udp_length_mem[(2**HEADER_FIFO_ADDR_WIDTH)-1:0];
276	reg [15:0] udp_checksum_mem[(2**HEADER_FIFO_ADDR_WIDTH)-1:0];
277	
278	reg [47:0] m_eth_dest_mac_reg = 48'd0;
279	reg [47:0] m_eth_src_mac_reg = 48'd0;
280	reg [15:0] m_eth_type_reg = 16'd0;
281	reg [3:0]  m_ip_version_reg = 4'd0;
282	reg [3:0]  m_ip_ihl_reg = 4'd0;
283	reg [5:0]  m_ip_dscp_reg = 6'd0;
284	reg [1:0]  m_ip_ecn_reg = 2'd0;
285	reg [15:0] m_ip_identification_reg = 16'd0;
286	reg [2:0]  m_ip_flags_reg = 3'd0;
287	reg [12:0] m_ip_fragment_offset_reg = 13'd0;
288	reg [7:0]  m_ip_ttl_reg = 8'd0;
289	reg [15:0] m_ip_header_checksum_reg = 16'd0;
290	reg [31:0] m_ip_source_ip_reg = 32'd0;
291	reg [31:0] m_ip_dest_ip_reg = 32'd0;
292	reg [15:0] m_udp_source_port_reg = 16'd0;
293	reg [15:0] m_udp_dest_port_reg = 16'd0;
294	reg [15:0] m_udp_length_reg = 16'd0;
295	reg [15:0] m_udp_checksum_reg = 16'd0;
296	
297	reg m_udp_hdr_valid_reg = 1'b0, m_udp_hdr_valid_next;
298	
299	// full when first MSB different but rest same
300	wire header_fifo_full = ((header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH] != header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH]) &&
301	                         (header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0] == header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]));
302	// empty when pointers match exactly
303	wire header_fifo_empty = header_fifo_wr_ptr_reg == header_fifo_rd_ptr_reg;
304	
305	// control signals
306	reg header_fifo_write;
307	reg header_fifo_read;
308	
309	wire header_fifo_ready = !header_fifo_full;
310	
311	assign m_udp_hdr_valid = m_udp_hdr_valid_reg;
312	
313	assign m_eth_dest_mac = m_eth_dest_mac_reg;
314	assign m_eth_src_mac = m_eth_src_mac_reg;
315	assign m_eth_type = m_eth_type_reg;
316	assign m_ip_version = m_ip_version_reg;
317	assign m_ip_ihl = m_ip_ihl_reg;
318	assign m_ip_dscp = m_ip_dscp_reg;
319	assign m_ip_ecn = m_ip_ecn_reg;
320	assign m_ip_length = m_udp_length_reg + 16'd20;
321	assign m_ip_identification = m_ip_identification_reg;
322	assign m_ip_flags = m_ip_flags_reg;
323	assign m_ip_fragment_offset = m_ip_fragment_offset_reg;
324	assign m_ip_ttl = m_ip_ttl_reg;
325	assign m_ip_protocol = 8'h11;
326	assign m_ip_header_checksum = m_ip_header_checksum_reg;
327	assign m_ip_source_ip = m_ip_source_ip_reg;
328	assign m_ip_dest_ip = m_ip_dest_ip_reg;
329	assign m_udp_source_port = m_udp_source_port_reg;
330	assign m_udp_dest_port = m_udp_dest_port_reg;
331	assign m_udp_length = m_udp_length_reg;
332	assign m_udp_checksum = m_udp_checksum_reg;
333	
334	// Write logic
335	always @* begin
336	    header_fifo_write = 1'b0;
337	
338	    header_fifo_wr_ptr_next = header_fifo_wr_ptr_reg;
339	
340	    if (hdr_valid_reg) begin
341	        // input data valid
342	        if (~header_fifo_full) begin
343	            // not full, perform write
344	            header_fifo_write = 1'b1;
345	            header_fifo_wr_ptr_next = header_fifo_wr_ptr_reg + 1;
346	        end
347	    end
348	end
349	
350	always @(posedge clk) begin
351	    if (rst) begin
352	        header_fifo_wr_ptr_reg <= {HEADER_FIFO_ADDR_WIDTH+1{1'b0}};
353	    end else begin
354	        header_fifo_wr_ptr_reg <= header_fifo_wr_ptr_next;
355	    end
356	
357	    if (header_fifo_write) begin
358	        eth_dest_mac_mem[header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]] <= eth_dest_mac_reg;
359	        eth_src_mac_mem[header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]] <= eth_src_mac_reg;
360	        eth_type_mem[header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]] <= eth_type_reg;
361	        ip_version_mem[header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]] <= ip_version_reg;
362	        ip_ihl_mem[header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]] <= ip_ihl_reg;
363	        ip_dscp_mem[header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]] <= ip_dscp_reg;
364	        ip_ecn_mem[header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]] <= ip_ecn_reg;
365	        ip_identification_mem[header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]] <= ip_identification_reg;
366	        ip_flags_mem[header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]] <= ip_flags_reg;
367	        ip_fragment_offset_mem[header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]] <= ip_fragment_offset_reg;
368	        ip_ttl_mem[header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]] <= ip_ttl_reg;
369	        ip_header_checksum_mem[header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]] <= ip_header_checksum_reg;
370	        ip_source_ip_mem[header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]] <= ip_source_ip_reg;
371	        ip_dest_ip_mem[header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]] <= ip_dest_ip_reg;
372	        udp_source_port_mem[header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]] <= udp_source_port_reg;
373	        udp_dest_port_mem[header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]] <= udp_dest_port_reg;
374	        udp_length_mem[header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]] <= frame_ptr_reg;
375	        udp_checksum_mem[header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]] <= checksum_reg[15:0];
376	    end
377	end
378	
379	// Read logic
380	always @* begin
381	    header_fifo_read = 1'b0;
382	
383	    header_fifo_rd_ptr_next = header_fifo_rd_ptr_reg;
384	
385	    m_udp_hdr_valid_next = m_udp_hdr_valid_reg;
386	
387	    if (m_udp_hdr_ready || !m_udp_hdr_valid) begin
388	        // output data not valid OR currently being transferred
389	        if (!header_fifo_empty) begin
390	            // not empty, perform read
391	            header_fifo_read = 1'b1;
392	            m_udp_hdr_valid_next = 1'b1;
393	            header_fifo_rd_ptr_next = header_fifo_rd_ptr_reg + 1;
394	        end else begin
395	            // empty, invalidate
396	            m_udp_hdr_valid_next = 1'b0;
397	        end
398	    end
399	end
400	
401	always @(posedge clk) begin
402	    if (rst) begin
403	        header_fifo_rd_ptr_reg <= {HEADER_FIFO_ADDR_WIDTH+1{1'b0}};
404	        m_udp_hdr_valid_reg <= 1'b0;
405	    end else begin
406	        header_fifo_rd_ptr_reg <= header_fifo_rd_ptr_next;
407	        m_udp_hdr_valid_reg <= m_udp_hdr_valid_next;
408	    end
409	
410	    if (header_fifo_read) begin
411	        m_eth_dest_mac_reg <= eth_dest_mac_mem[header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]];
412	        m_eth_src_mac_reg <= eth_src_mac_mem[header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]];
413	        m_eth_type_reg <= eth_type_mem[header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]];
414	        m_ip_version_reg <= ip_version_mem[header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]];
415	        m_ip_ihl_reg <= ip_ihl_mem[header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]];
416	        m_ip_dscp_reg <= ip_dscp_mem[header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]];
417	        m_ip_ecn_reg <= ip_ecn_mem[header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]];
418	        m_ip_identification_reg <= ip_identification_mem[header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]];
419	        m_ip_flags_reg <= ip_flags_mem[header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]];
420	        m_ip_fragment_offset_reg <= ip_fragment_offset_mem[header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]];
421	        m_ip_ttl_reg <= ip_ttl_mem[header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]];
422	        m_ip_header_checksum_reg <= ip_header_checksum_mem[header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]];
423	        m_ip_source_ip_reg <= ip_source_ip_mem[header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]];
424	        m_ip_dest_ip_reg <= ip_dest_ip_mem[header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]];
425	        m_udp_source_port_reg <= udp_source_port_mem[header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]];
426	        m_udp_dest_port_reg <= udp_dest_port_mem[header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]];
427	        m_udp_length_reg <= udp_length_mem[header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]];
428	        m_udp_checksum_reg <= udp_checksum_mem[header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]];
429	    end
430	end
431	
432	assign s_udp_hdr_ready = s_udp_hdr_ready_reg;
433	
434	assign busy = busy_reg;
435	
436	always @* begin
437	    state_next = STATE_IDLE;
438	
439	    s_udp_hdr_ready_next = 1'b0;
440	    s_udp_payload_axis_tready_next = 1'b0;
441	
442	    store_udp_hdr = 1'b0;
443	    shift_payload_in = 1'b0;
444	
445	    frame_ptr_next = frame_ptr_reg;
446	    checksum_next = checksum_reg;
447	
448	    hdr_valid_next = 1'b0;
449	
450	    case (state_reg)
451	        STATE_IDLE: begin
452	            // idle state
453	            s_udp_hdr_ready_next = header_fifo_ready;
454	
455	            if (s_udp_hdr_ready && s_udp_hdr_valid) begin
456	                store_udp_hdr = 1'b1;
457	                frame_ptr_next = 0;
458	                // 16'h0011 = zero padded type field
459	                // 16'h0010 = header length times two
460	                checksum_next = 16'h0011 + 16'h0010;
461	                s_udp_hdr_ready_next = 1'b0;
462	                state_next = STATE_SUM_HEADER_1;
463	            end else begin
464	                state_next = STATE_IDLE;
465	            end
466	        end
467	        STATE_SUM_HEADER_1: begin
468	            // sum pseudo header and header
469	            checksum_next = checksum_reg + ip_source_ip_reg[31:16] + ip_source_ip_reg[15:0];
470	            state_next = STATE_SUM_HEADER_2;
471	        end
472	        STATE_SUM_HEADER_2: begin
473	            // sum pseudo header and header
474	            checksum_next = checksum_reg + ip_dest_ip_reg[31:16] + ip_dest_ip_reg[15:0];
475	            state_next = STATE_SUM_HEADER_3;
476	        end
477	        STATE_SUM_HEADER_3: begin
478	            // sum pseudo header and header
479	            checksum_next = checksum_reg + udp_source_port_reg + udp_dest_port_reg;
480	            frame_ptr_next = 8;
481	            state_next = STATE_SUM_PAYLOAD;
482	        end
483	        STATE_SUM_PAYLOAD: begin
484	            // sum payload
485	            shift_payload_in = 1'b1;
486	
487	            if (s_udp_payload_axis_tready && s_udp_payload_axis_tvalid) begin
488	                // checksum computation for payload - alternately store and accumulate
489	                // add 2 for length calculation (two length fields in pseudo header)
490	                if (frame_ptr_reg[0]) begin
491	                    checksum_next = checksum_reg + {8'h00, s_udp_payload_axis_tdata} + 2;
492	                end else begin
493	                    checksum_next = checksum_reg + {s_udp_payload_axis_tdata, 8'h00} + 2;
494	                end
495	
496	                frame_ptr_next = frame_ptr_reg + 1;
497	
498	                if (s_udp_payload_axis_tlast) begin
499	                    state_next = STATE_FINISH_SUM;
500	                end else begin
501	                    state_next = STATE_SUM_PAYLOAD;
502	                end
503	            end else begin
504	                state_next = STATE_SUM_PAYLOAD;
505	            end
506	        end
507	        STATE_FINISH_SUM: begin
508	            // add MSW (twice!) for proper ones complement sum
509	            checksum_part = checksum_reg[15:0] + checksum_reg[31:16];
510	            checksum_next = ~(checksum_part[15:0] + checksum_part[16]);
511	            hdr_valid_next = 1;
512	            state_next = STATE_IDLE;
513	        end
514	    endcase
515	end
516	
517	always @(posedge clk) begin
518	    if (rst) begin
519	        state_reg <= STATE_IDLE;
520	        s_udp_hdr_ready_reg <= 1'b0;
521	        s_udp_payload_axis_tready_reg <= 1'b0;
522	        hdr_valid_reg <= 1'b0;
523	        busy_reg <= 1'b0;
524	    end else begin
525	        state_reg <= state_next;
526	
527	        s_udp_hdr_ready_reg <= s_udp_hdr_ready_next;
528	        s_udp_payload_axis_tready_reg <= s_udp_payload_axis_tready_next;
529	
530	        hdr_valid_reg <= hdr_valid_next;
531	
532	        busy_reg <= state_next != STATE_IDLE;
533	    end
534	
535	    frame_ptr_reg <= frame_ptr_next;
536	    checksum_reg <= checksum_next;
537	
538	    // datapath
539	    if (store_udp_hdr) begin
540	        eth_dest_mac_reg <= s_eth_dest_mac;
541	        eth_src_mac_reg <= s_eth_src_mac;
542	        eth_type_reg <= s_eth_type;
543	        ip_version_reg <= s_ip_version;
544	        ip_ihl_reg <= s_ip_ihl;
545	        ip_dscp_reg <= s_ip_dscp;
546	        ip_ecn_reg <= s_ip_ecn;
547	        ip_identification_reg <= s_ip_identification;
548	        ip_flags_reg <= s_ip_flags;
549	        ip_fragment_offset_reg <= s_ip_fragment_offset;
550	        ip_ttl_reg <= s_ip_ttl;
551	        ip_header_checksum_reg <= s_ip_header_checksum;
552	        ip_source_ip_reg <= s_ip_source_ip;
553	        ip_dest_ip_reg <= s_ip_dest_ip;
554	        udp_source_port_reg <= s_udp_source_port;
555	        udp_dest_port_reg <= s_udp_dest_port;
556	    end
557	end
558	
559	endmodule
560	
561	`resetall
562

