33	 */
34	module udp_checksum_gen_64 #
35	(
36	    parameter PAYLOAD_FIFO_DEPTH = 2048,
37	    parameter HEADER_FIFO_DEPTH = 8
38	)
39	(
40	    input  wire        clk,
41	    input  wire        rst,
42	    
43	    /*
44	     * UDP frame input
45	     */
46	    input  wire        s_udp_hdr_valid,
47	    output wire        s_udp_hdr_ready,
48	    input  wire [47:0] s_eth_dest_mac,
49	    input  wire [47:0] s_eth_src_mac,
50	    input  wire [15:0] s_eth_type,
51	    input  wire [3:0]  s_ip_version,
52	    input  wire [3:0]  s_ip_ihl,
53	    input  wire [5:0]  s_ip_dscp,
54	    input  wire [1:0]  s_ip_ecn,
55	    input  wire [15:0] s_ip_identification,
56	    input  wire [2:0]  s_ip_flags,
57	    input  wire [12:0] s_ip_fragment_offset,
58	    input  wire [7:0]  s_ip_ttl,
59	    input  wire [15:0] s_ip_header_checksum,
60	    input  wire [31:0] s_ip_source_ip,
61	    input  wire [31:0] s_ip_dest_ip,
62	    input  wire [15:0] s_udp_source_port,
63	    input  wire [15:0] s_udp_dest_port,
64	    input  wire [63:0] s_udp_payload_axis_tdata,
65	    input  wire [7:0]  s_udp_payload_axis_tkeep,
66	    input  wire        s_udp_payload_axis_tvalid,
67	    output wire        s_udp_payload_axis_tready,
68	    input  wire        s_udp_payload_axis_tlast,
69	    input  wire        s_udp_payload_axis_tuser,
70	    
71	    /*
72	     * UDP frame output
73	     */
74	    output wire        m_udp_hdr_valid,
75	    input  wire        m_udp_hdr_ready,
76	    output wire [47:0] m_eth_dest_mac,
77	    output wire [47:0] m_eth_src_mac,
78	    output wire [15:0] m_eth_type,
79	    output wire [3:0]  m_ip_version,
80	    output wire [3:0]  m_ip_ihl,
81	    output wire [5:0]  m_ip_dscp,
82	    output wire [1:0]  m_ip_ecn,
83	    output wire [15:0] m_ip_length,
84	    output wire [15:0] m_ip_identification,
85	    output wire [2:0]  m_ip_flags,
86	    output wire [12:0] m_ip_fragment_offset,
87	    output wire [7:0]  m_ip_ttl,
88	    output wire [7:0]  m_ip_protocol,
89	    output wire [15:0] m_ip_header_checksum,
90	    output wire [31:0] m_ip_source_ip,
91	    output wire [31:0] m_ip_dest_ip,
92	    output wire [15:0] m_udp_source_port,
93	    output wire [15:0] m_udp_dest_port,
94	    output wire [15:0] m_udp_length,
95	    output wire [15:0] m_udp_checksum,
96	    output wire [63:0] m_udp_payload_axis_tdata,
97	    output wire [7:0]  m_udp_payload_axis_tkeep,
98	    output wire        m_udp_payload_axis_tvalid,
99	    input  wire        m_udp_payload_axis_tready,
100	    output wire        m_udp_payload_axis_tlast,
101	    output wire        m_udp_payload_axis_tuser,
102	    
103	    /*
104	     * Status signals
105	     */
106	    output wire        busy
107	);
108	
109	/*
110	
111	UDP Frame
112	
113	 Field                       Length
114	 Destination MAC address     6 octets
115	 Source MAC address          6 octets
116	 Ethertype (0x0800)          2 octets
117	 Version (4)                 4 bits
118	 IHL (5-15)                  4 bits
119	 DSCP (0)                    6 bits
120	 ECN (0)                     2 bits
121	 length                      2 octets
122	 identification (0?)         2 octets
123	 flags (010)                 3 bits
124	 fragment offset (0)         13 bits
125	 time to live (64?)          1 octet
126	 protocol                    1 octet
127	 header checksum             2 octets
128	 source IP                   4 octets
129	 destination IP              4 octets
130	 options                     (IHL-5)*4 octets
131	
132	 source port                 2 octets
133	 desination port             2 octets
134	 length                      2 octets
135	 checksum                    2 octets
136	
137	 payload                     length octets
138	
139	This module receives a UDP frame with header fields in parallel and payload on
140	an AXI stream interface, calculates the length and checksum, then produces the
141	header fields in parallel along with the UDP payload in a separate AXI stream.
142	
143	*/
144	
145	parameter HEADER_FIFO_ADDR_WIDTH = $clog2(HEADER_FIFO_DEPTH);
146	
147	localparam [2:0]
148	    STATE_IDLE = 3'd0,
149	    STATE_SUM_HEADER = 3'd1,
150	    STATE_SUM_PAYLOAD = 3'd2,
151	    STATE_FINISH_SUM_1 = 3'd3,
152	    STATE_FINISH_SUM_2 = 3'd4;
153	
154	reg [2:0] state_reg = STATE_IDLE, state_next;
155	
156	// datapath control signals
157	reg store_udp_hdr;
158	reg shift_payload_in;
159	reg [31:0] checksum_part;
160	
161	reg [15:0] frame_ptr_reg = 16'd0, frame_ptr_next;
162	
163	reg [31:0] checksum_reg = 32'd0, checksum_next;
164	reg [16:0] checksum_temp1_reg = 17'd0, checksum_temp1_next;
165	reg [16:0] checksum_temp2_reg = 17'd0, checksum_temp2_next;
166	
167	reg [47:0] eth_dest_mac_reg = 48'd0;
168	reg [47:0] eth_src_mac_reg = 48'd0;
169	reg [15:0] eth_type_reg = 16'd0;
170	reg [3:0]  ip_version_reg = 4'd0;
171	reg [3:0]  ip_ihl_reg = 4'd0;
172	reg [5:0]  ip_dscp_reg = 6'd0;
173	reg [1:0]  ip_ecn_reg = 2'd0;
174	reg [15:0] ip_identification_reg = 16'd0;
175	reg [2:0]  ip_flags_reg = 3'd0;
176	reg [12:0] ip_fragment_offset_reg = 13'd0;
177	reg [7:0]  ip_ttl_reg = 8'd0;
178	reg [15:0] ip_header_checksum_reg = 16'd0;
179	reg [31:0] ip_source_ip_reg = 32'd0;
180	reg [31:0] ip_dest_ip_reg = 32'd0;
181	reg [15:0] udp_source_port_reg = 16'd0;
182	reg [15:0] udp_dest_port_reg = 16'd0;
183	
184	reg hdr_valid_reg = 0, hdr_valid_next;
185	
186	reg s_udp_hdr_ready_reg = 1'b0, s_udp_hdr_ready_next;
187	reg s_udp_payload_axis_tready_reg = 1'b0, s_udp_payload_axis_tready_next;
188	
189	reg busy_reg = 1'b0;
190	
191	/*
192	 * UDP Payload FIFO
193	 */
194	wire [63:0] s_udp_payload_fifo_tdata;
195	wire [7:0] s_udp_payload_fifo_tkeep;
196	wire s_udp_payload_fifo_tvalid;
197	wire s_udp_payload_fifo_tready;
198	wire s_udp_payload_fifo_tlast;
199	wire s_udp_payload_fifo_tuser;
200	
