202	wire [7:0] m_udp_payload_fifo_tkeep;
203	wire m_udp_payload_fifo_tvalid;
204	wire m_udp_payload_fifo_tready;
205	wire m_udp_payload_fifo_tlast;
206	wire m_udp_payload_fifo_tuser;
207	
208	axis_fifo #(
209	    .DEPTH(PAYLOAD_FIFO_DEPTH),
210	    .DATA_WIDTH(64),
211	    .KEEP_ENABLE(1),
212	    .KEEP_WIDTH(8),
213	    .LAST_ENABLE(1),
214	    .ID_ENABLE(0),
215	    .DEST_ENABLE(0),
216	    .USER_ENABLE(1),
217	    .USER_WIDTH(1),
218	    .FRAME_FIFO(0)
219	)
220	payload_fifo (
221	    .clk(clk),
222	    .rst(rst),
223	    // AXI input
224	    .s_axis_tdata(s_udp_payload_fifo_tdata),
225	    .s_axis_tkeep(s_udp_payload_fifo_tkeep),
226	    .s_axis_tvalid(s_udp_payload_fifo_tvalid),
227	    .s_axis_tready(s_udp_payload_fifo_tready),
228	    .s_axis_tlast(s_udp_payload_fifo_tlast),
229	    .s_axis_tid(0),
230	    .s_axis_tdest(0),
231	    .s_axis_tuser(s_udp_payload_fifo_tuser),
232	    // AXI output
233	    .m_axis_tdata(m_udp_payload_fifo_tdata),
234	    .m_axis_tkeep(m_udp_payload_fifo_tkeep),
235	    .m_axis_tvalid(m_udp_payload_fifo_tvalid),
236	    .m_axis_tready(m_udp_payload_fifo_tready),
237	    .m_axis_tlast(m_udp_payload_fifo_tlast),
238	    .m_axis_tid(),
239	    .m_axis_tdest(),
240	    .m_axis_tuser(m_udp_payload_fifo_tuser),
241	    // Status
242	    .status_overflow(),
243	    .status_bad_frame(),
244	    .status_good_frame()
245	);
246	
247	assign s_udp_payload_fifo_tdata = s_udp_payload_axis_tdata;
248	assign s_udp_payload_fifo_tkeep = s_udp_payload_axis_tkeep;
249	assign s_udp_payload_fifo_tvalid = s_udp_payload_axis_tvalid && shift_payload_in;
250	assign s_udp_payload_axis_tready = s_udp_payload_fifo_tready && shift_payload_in;
251	assign s_udp_payload_fifo_tlast = s_udp_payload_axis_tlast;
252	assign s_udp_payload_fifo_tuser = s_udp_payload_axis_tuser;
253	
254	assign m_udp_payload_axis_tdata = m_udp_payload_fifo_tdata;
255	assign m_udp_payload_axis_tkeep = m_udp_payload_fifo_tkeep;
256	assign m_udp_payload_axis_tvalid = m_udp_payload_fifo_tvalid;
257	assign m_udp_payload_fifo_tready = m_udp_payload_axis_tready;
258	assign m_udp_payload_axis_tlast = m_udp_payload_fifo_tlast;
259	assign m_udp_payload_axis_tuser = m_udp_payload_fifo_tuser;
260	
261	/*
262	 * UDP Header FIFO
263	 */
264	reg [HEADER_FIFO_ADDR_WIDTH:0] header_fifo_wr_ptr_reg = {HEADER_FIFO_ADDR_WIDTH+1{1'b0}}, header_fifo_wr_ptr_next;
265	reg [HEADER_FIFO_ADDR_WIDTH:0] header_fifo_rd_ptr_reg = {HEADER_FIFO_ADDR_WIDTH+1{1'b0}}, header_fifo_rd_ptr_next;
266	
267	reg [47:0] eth_dest_mac_mem[(2**HEADER_FIFO_ADDR_WIDTH)-1:0];
268	reg [47:0] eth_src_mac_mem[(2**HEADER_FIFO_ADDR_WIDTH)-1:0];
269	reg [15:0] eth_type_mem[(2**HEADER_FIFO_ADDR_WIDTH)-1:0];
270	reg [3:0] ip_version_mem[(2**HEADER_FIFO_ADDR_WIDTH)-1:0];
271	reg [3:0] ip_ihl_mem[(2**HEADER_FIFO_ADDR_WIDTH)-1:0];
272	reg [5:0] ip_dscp_mem[(2**HEADER_FIFO_ADDR_WIDTH)-1:0];
273	reg [1:0] ip_ecn_mem[(2**HEADER_FIFO_ADDR_WIDTH)-1:0];
274	reg [15:0] ip_identification_mem[(2**HEADER_FIFO_ADDR_WIDTH)-1:0];
275	reg [2:0] ip_flags_mem[(2**HEADER_FIFO_ADDR_WIDTH)-1:0];
276	reg [12:0] ip_fragment_offset_mem[(2**HEADER_FIFO_ADDR_WIDTH)-1:0];
277	reg [7:0] ip_ttl_mem[(2**HEADER_FIFO_ADDR_WIDTH)-1:0];
278	reg [15:0] ip_header_checksum_mem[(2**HEADER_FIFO_ADDR_WIDTH)-1:0];
279	reg [31:0] ip_source_ip_mem[(2**HEADER_FIFO_ADDR_WIDTH)-1:0];
280	reg [31:0] ip_dest_ip_mem[(2**HEADER_FIFO_ADDR_WIDTH)-1:0];
281	reg [15:0] udp_source_port_mem[(2**HEADER_FIFO_ADDR_WIDTH)-1:0];
282	reg [15:0] udp_dest_port_mem[(2**HEADER_FIFO_ADDR_WIDTH)-1:0];
283	reg [15:0] udp_length_mem[(2**HEADER_FIFO_ADDR_WIDTH)-1:0];
284	reg [15:0] udp_checksum_mem[(2**HEADER_FIFO_ADDR_WIDTH)-1:0];
285	
286	reg [47:0] m_eth_dest_mac_reg = 48'd0;
287	reg [47:0] m_eth_src_mac_reg = 48'd0;
288	reg [15:0] m_eth_type_reg = 16'd0;
289	reg [3:0]  m_ip_version_reg = 4'd0;
290	reg [3:0]  m_ip_ihl_reg = 4'd0;
291	reg [5:0]  m_ip_dscp_reg = 6'd0;
292	reg [1:0]  m_ip_ecn_reg = 2'd0;
293	reg [15:0] m_ip_identification_reg = 16'd0;
294	reg [2:0]  m_ip_flags_reg = 3'd0;
295	reg [12:0] m_ip_fragment_offset_reg = 13'd0;
296	reg [7:0]  m_ip_ttl_reg = 8'd0;
297	reg [15:0] m_ip_header_checksum_reg = 16'd0;
298	reg [31:0] m_ip_source_ip_reg = 32'd0;
299	reg [31:0] m_ip_dest_ip_reg = 32'd0;
300	reg [15:0] m_udp_source_port_reg = 16'd0;
301	reg [15:0] m_udp_dest_port_reg = 16'd0;
302	reg [15:0] m_udp_length_reg = 16'd0;
303	reg [15:0] m_udp_checksum_reg = 16'd0;
304	
305	reg m_udp_hdr_valid_reg = 1'b0, m_udp_hdr_valid_next;
306	
307	// full when first MSB different but rest same
308	wire header_fifo_full = ((header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH] != header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH]) &&
309	                         (header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0] == header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]));
310	// empty when pointers match exactly
311	wire header_fifo_empty = header_fifo_wr_ptr_reg == header_fifo_rd_ptr_reg;
312	
313	// control signals
314	reg header_fifo_write;
315	reg header_fifo_read;
316	
317	wire header_fifo_ready = !header_fifo_full;
318	
319	assign m_udp_hdr_valid = m_udp_hdr_valid_reg;
320	
321	assign m_eth_dest_mac = m_eth_dest_mac_reg;
322	assign m_eth_src_mac = m_eth_src_mac_reg;
323	assign m_eth_type = m_eth_type_reg;
324	assign m_ip_version = m_ip_version_reg;
325	assign m_ip_ihl = m_ip_ihl_reg;
326	assign m_ip_dscp = m_ip_dscp_reg;
327	assign m_ip_ecn = m_ip_ecn_reg;
328	assign m_ip_length = m_udp_length_reg + 16'd20;
329	assign m_ip_identification = m_ip_identification_reg;
330	assign m_ip_flags = m_ip_flags_reg;
331	assign m_ip_fragment_offset = m_ip_fragment_offset_reg;
332	assign m_ip_ttl = m_ip_ttl_reg;
333	assign m_ip_protocol = 8'h11;
334	assign m_ip_header_checksum = m_ip_header_checksum_reg;
335	assign m_ip_source_ip = m_ip_source_ip_reg;
336	assign m_ip_dest_ip = m_ip_dest_ip_reg;
337	assign m_udp_source_port = m_udp_source_port_reg;
338	assign m_udp_dest_port = m_udp_dest_port_reg;
339	assign m_udp_length = m_udp_length_reg;
340	assign m_udp_checksum = m_udp_checksum_reg;
341	
342	// Write logic
343	always @* begin
344	    header_fifo_write = 1'b0;
345	
346	    header_fifo_wr_ptr_next = header_fifo_wr_ptr_reg;
347	
348	    if (hdr_valid_reg) begin
349	        // input data valid
350	        if (~header_fifo_full) begin
351	            // not full, perform write
352	            header_fifo_write = 1'b1;
353	            header_fifo_wr_ptr_next = header_fifo_wr_ptr_reg + 1;
354	        end
355	    end
356	end
357	
358	always @(posedge clk) begin
359	    if (rst) begin
360	        header_fifo_wr_ptr_reg <= {HEADER_FIFO_ADDR_WIDTH+1{1'b0}};
361	    end else begin
362	        header_fifo_wr_ptr_reg <= header_fifo_wr_ptr_next;
363	    end
364	
365	    if (header_fifo_write) begin
366	        eth_dest_mac_mem[header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]] <= eth_dest_mac_reg;
367	        eth_src_mac_mem[header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]] <= eth_src_mac_reg;
368	        eth_type_mem[header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]] <= eth_type_reg;
369	        ip_version_mem[header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]] <= ip_version_reg;
370	        ip_ihl_mem[header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]] <= ip_ihl_reg;
371	        ip_dscp_mem[header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]] <= ip_dscp_reg;
372	        ip_ecn_mem[header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]] <= ip_ecn_reg;
373	        ip_identification_mem[header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]] <= ip_identification_reg;
374	        ip_flags_mem[header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]] <= ip_flags_reg;
375	        ip_fragment_offset_mem[header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]] <= ip_fragment_offset_reg;
376	        ip_ttl_mem[header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]] <= ip_ttl_reg;
377	        ip_header_checksum_mem[header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]] <= ip_header_checksum_reg;
378	        ip_source_ip_mem[header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]] <= ip_source_ip_reg;
379	        ip_dest_ip_mem[header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]] <= ip_dest_ip_reg;
380	        udp_source_port_mem[header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]] <= udp_source_port_reg;
381	        udp_dest_port_mem[header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]] <= udp_dest_port_reg;
382	        udp_length_mem[header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]] <= frame_ptr_reg;
383	        udp_checksum_mem[header_fifo_wr_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]] <= checksum_reg[15:0];
384	    end
385	end
386	
387	// Read logic
388	always @* begin
389	    header_fifo_read = 1'b0;
390	
391	    header_fifo_rd_ptr_next = header_fifo_rd_ptr_reg;
392	
393	    m_udp_hdr_valid_next = m_udp_hdr_valid_reg;
394	
395	    if (m_udp_hdr_ready || !m_udp_hdr_valid) begin
396	        // output data not valid OR currently being transferred
397	        if (!header_fifo_empty) begin
398	            // not empty, perform read
399	            header_fifo_read = 1'b1;
400	            m_udp_hdr_valid_next = 1'b1;
401	            header_fifo_rd_ptr_next = header_fifo_rd_ptr_reg + 1;
402	        end else begin
403	            // empty, invalidate
404	            m_udp_hdr_valid_next = 1'b0;
405	        end
406	    end
407	end
408	
409	always @(posedge clk) begin
410	    if (rst) begin
411	        header_fifo_rd_ptr_reg <= {HEADER_FIFO_ADDR_WIDTH+1{1'b0}};
412	        m_udp_hdr_valid_reg <= 1'b0;
413	    end else begin
414	        header_fifo_rd_ptr_reg <= header_fifo_rd_ptr_next;
415	        m_udp_hdr_valid_reg <= m_udp_hdr_valid_next;
416	    end
417	
418	    if (header_fifo_read) begin
419	        m_eth_dest_mac_reg <= eth_dest_mac_mem[header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]];
420	        m_eth_src_mac_reg <= eth_src_mac_mem[header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]];
421	        m_eth_type_reg <= eth_type_mem[header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]];
422	        m_ip_version_reg <= ip_version_mem[header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]];
423	        m_ip_ihl_reg <= ip_ihl_mem[header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]];
424	        m_ip_dscp_reg <= ip_dscp_mem[header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]];
425	        m_ip_ecn_reg <= ip_ecn_mem[header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]];
426	        m_ip_identification_reg <= ip_identification_mem[header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]];
427	        m_ip_flags_reg <= ip_flags_mem[header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]];
428	        m_ip_fragment_offset_reg <= ip_fragment_offset_mem[header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]];
429	        m_ip_ttl_reg <= ip_ttl_mem[header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]];
430	        m_ip_header_checksum_reg <= ip_header_checksum_mem[header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]];
431	        m_ip_source_ip_reg <= ip_source_ip_mem[header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]];
432	        m_ip_dest_ip_reg <= ip_dest_ip_mem[header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]];
433	        m_udp_source_port_reg <= udp_source_port_mem[header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]];
434	        m_udp_dest_port_reg <= udp_dest_port_mem[header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]];
435	        m_udp_length_reg <= udp_length_mem[header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]];
436	        m_udp_checksum_reg <= udp_checksum_mem[header_fifo_rd_ptr_reg[HEADER_FIFO_ADDR_WIDTH-1:0]];
437	    end
438	end
439	
440	assign s_udp_hdr_ready = s_udp_hdr_ready_reg;
441	
442	assign busy = busy_reg;
443	
444	integer i, word_cnt;
445	
446	always @* begin
447	    state_next = STATE_IDLE;
448	
449	    s_udp_hdr_ready_next = 1'b0;
450	    s_udp_payload_axis_tready_next = 1'b0;
451	
452	    store_udp_hdr = 1'b0;
453	    shift_payload_in = 1'b0;
454	
455	    frame_ptr_next = frame_ptr_reg;
456	    checksum_next = checksum_reg;
457	    checksum_temp1_next = checksum_temp1_reg;
458	    checksum_temp2_next = checksum_temp2_reg;
459	
460	    hdr_valid_next = 1'b0;
461	
462	    case (state_reg)
463	        STATE_IDLE: begin
464	            // idle state
465	            s_udp_hdr_ready_next = header_fifo_ready;
466	
467	            if (s_udp_hdr_ready && s_udp_hdr_valid) begin
468	                store_udp_hdr = 1'b1;
469	                frame_ptr_next = 0;
470	                // 16'h0011 = zero padded type field
471	                // 16'h0010 = header length times two
472	                checksum_next = 16'h0011 + 16'h0010;
473	                checksum_temp1_next = s_ip_source_ip[31:16];
474	                checksum_temp2_next = s_ip_source_ip[15:0];
475	                s_udp_hdr_ready_next = 1'b0;
476	                state_next = STATE_SUM_HEADER;
477	            end else begin
478	                state_next = STATE_IDLE;
479	            end
480	        end
481	        STATE_SUM_HEADER: begin
482	            // sum pseudo header and header
483	            checksum_next = checksum_reg + checksum_temp1_reg + checksum_temp2_reg;
484	            checksum_temp1_next = ip_dest_ip_reg[31:16] + ip_dest_ip_reg[15:0];
485	            checksum_temp2_next = udp_source_port_reg + udp_dest_port_reg;
486	            frame_ptr_next = 8;
487	            state_next = STATE_SUM_PAYLOAD;
488	        end
489	        STATE_SUM_PAYLOAD: begin
490	            // sum payload
491	            shift_payload_in = 1'b1;
492	
493	            if (s_udp_payload_axis_tready && s_udp_payload_axis_tvalid) begin
494	                word_cnt = 1;
495	                for (i = 1; i <= 8; i = i + 1) begin
496	                    if (s_udp_payload_axis_tkeep == 8'hff >> (8-i)) word_cnt = i;
497	                end
498	
499	                checksum_temp1_next = 0;
500	                checksum_temp2_next = 0;
501	
502	                for (i = 0; i < 4; i = i + 1) begin
503	                    if (s_udp_payload_axis_tkeep[i]) begin
504	                        if (i & 1) begin
505	                            checksum_temp1_next = checksum_temp1_next + {8'h00, s_udp_payload_axis_tdata[i*8 +: 8]};
506	                        end else begin
507	                            checksum_temp1_next = checksum_temp1_next + {s_udp_payload_axis_tdata[i*8 +: 8], 8'h00};
508	                        end
509	                    end
510	                end
511	
512	                for (i = 4; i < 8; i = i + 1) begin
513	                    if (s_udp_payload_axis_tkeep[i]) begin
514	                        if (i & 1) begin
515	                            checksum_temp2_next = checksum_temp2_next + {8'h00, s_udp_payload_axis_tdata[i*8 +: 8]};
516	                        end else begin
517	                            checksum_temp2_next = checksum_temp2_next + {s_udp_payload_axis_tdata[i*8 +: 8], 8'h00};
518	                        end
519	                    end
520	                end
521	
522	                // add length * 2 (two copies of length field in pseudo header)
523	                checksum_next = checksum_reg + checksum_temp1_reg + checksum_temp2_reg + (word_cnt << 1);
524	
525	                frame_ptr_next = frame_ptr_reg + word_cnt;
526	
527	                if (s_udp_payload_axis_tlast) begin
528	                    state_next = STATE_FINISH_SUM_1;
529	                end else begin
530	                    state_next = STATE_SUM_PAYLOAD;
531	                end
532	            end else begin
533	                state_next = STATE_SUM_PAYLOAD;
534	            end
535	        end
536	        STATE_FINISH_SUM_1: begin
537	            // empty pipeline
538	            checksum_next = checksum_reg + checksum_temp1_reg + checksum_temp2_reg;
539	            state_next = STATE_FINISH_SUM_2;
540	        end
541	        STATE_FINISH_SUM_2: begin
542	            // add MSW (twice!) for proper ones complement sum
543	            checksum_part = checksum_reg[15:0] + checksum_reg[31:16];
544	            checksum_next = ~(checksum_part[15:0] + checksum_part[16]);
545	            hdr_valid_next = 1;
546	            state_next = STATE_IDLE;
547	        end
548	    endcase
549	end
550	
551	always @(posedge clk) begin
552	    if (rst) begin
553	        state_reg <= STATE_IDLE;
554	        s_udp_hdr_ready_reg <= 1'b0;
555	        s_udp_payload_axis_tready_reg <= 1'b0;
556	        hdr_valid_reg <= 1'b0;
557	        busy_reg <= 1'b0;
558	    end else begin
559	        state_reg <= state_next;
560	
561	        s_udp_hdr_ready_reg <= s_udp_hdr_ready_next;
562	        s_udp_payload_axis_tready_reg <= s_udp_payload_axis_tready_next;
563	
564	        hdr_valid_reg <= hdr_valid_next;
565	
566	        busy_reg <= state_next != STATE_IDLE;
567	    end
568	
569	    frame_ptr_reg <= frame_ptr_next;
570	    checksum_reg <= checksum_next;
571	    checksum_temp1_reg <= checksum_temp1_next;
572	    checksum_temp2_reg <= checksum_temp2_next;
573	
574	    // datapath
575	    if (store_udp_hdr) begin
576	        eth_dest_mac_reg <= s_eth_dest_mac;
577	        eth_src_mac_reg <= s_eth_src_mac;
578	        eth_type_reg <= s_eth_type;
579	        ip_version_reg <= s_ip_version;
580	        ip_ihl_reg <= s_ip_ihl;
581	        ip_dscp_reg <= s_ip_dscp;
582	        ip_ecn_reg <= s_ip_ecn;
583	        ip_identification_reg <= s_ip_identification;
584	        ip_flags_reg <= s_ip_flags;
585	        ip_fragment_offset_reg <= s_ip_fragment_offset;
586	        ip_ttl_reg <= s_ip_ttl;
587	        ip_header_checksum_reg <= s_ip_header_checksum;
588	        ip_source_ip_reg <= s_ip_source_ip;
589	        ip_dest_ip_reg <= s_ip_dest_ip;
590	        udp_source_port_reg <= s_udp_source_port;
591	        udp_dest_port_reg <= s_udp_dest_port;
592	    end
593	end
594	
595	endmodule
596	
597	`resetall
598

